// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }
    function testFuzz_property(uint128 vBase, uint128 vNft, uint56 chFee, uint16 fRate, bytes32 root, bool useOracle, bool payRoyal) public {
        address _nft = address(0x1234);
        address _baseToken = address(0);
        vm.assume(fRate <= 5000);
        vm.assume(_nft != address(0));
        vm.prank(address(this));
        c.initialize(_baseToken, _nft, vBase, vNft, chFee, fRate, root, useOracle, payRoyal);
        assertTrue(c.nft() == _nft);
    }
}
